# owner: platform
"""Contact sheet rows for substitute teachers."""

from typing import List, Tuple

from rosterkit.models import Student
from rosterkit.errors import ProjectError

GAP = "  "

def check_students(students: List[Student]) -> None:
    """Refuse an empty list or a student with no email."""
    if not students:
        raise ProjectError("no students for contact sheet")
    for student in students:
        if not (student.email or "").strip():
            raise ProjectError(
                f"no email for {student.display_name}"
            )

def sort_key(student: Student) -> Tuple[str, str]:
    name = student.display_name.lower()
    return (name, student.student_id)

def cell_values(student: Student) -> List[str]:
    return [
        student.display_name,
        student.section,
        student.email.strip()
    ]

def column_widths(cells: List[List[str]]) -> List[int]:
    columns = zip(*cells)
    return [max(map(len, group)) for group in columns]

def format_row(cells: List[str], widths: List[int]) -> str:
    padded = [
        text.ljust(size)
        for text, size in zip(cells, widths)
    ]
    return GAP.join(padded).rstrip()

def contact_rows(students: List[Student]) -> List[str]:
    """Text rows of name, section, email, sorted by name."""
    check_students(students)
    ordered = sorted(students, key=sort_key)
    cells = [cell_values(item) for item in ordered]
    widths = column_widths(cells)
    return [format_row(item, widths) for item in cells]
